/* Decorative effects are independent of jQuery and the theme bundle. */
(() => {
  'use strict';
  const canvas = document.getElementById('pink-laser-canvas');
  const ctx = canvas && canvas.getContext('2d');
  if (!ctx) return;
  const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
  const finePointer = matchMedia('(hover: hover) and (pointer: fine)');
  let width = 0;
  let height = 0;
  let frame = 0;
  let lastFrame = 0;
  let phase = 0;
  const trail = document.createElement('canvas');
  trail.id = 'pink-cursor-trail';
  trail.setAttribute('aria-hidden', 'true');
  document.body.appendChild(trail);
  const trailCtx = trail.getContext('2d');
  const points = [];
  let spotlight = null;
  let pointerX = 0;
  let pointerY = 0;
  let pointerActive = false;

  function resize() {
    width = innerWidth;
    height = innerHeight;
    const ratio = Math.min(devicePixelRatio || 1, 1.5);
    for (const surface of [canvas, trail]) {
      surface.width = Math.round(width * ratio);
      surface.height = Math.round(height * ratio);
      surface.style.width = width + 'px';
      surface.style.height = height + 'px';
    }
    ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
    if (trailCtx) trailCtx.setTransform(ratio, 0, 0, ratio, 0, 0);
  }

  function drawBeams() {
    ctx.clearRect(0, 0, width, height);
    const driftX = pointerActive ? (pointerX / width - 0.5) * 30 : 0;
    for (let i = 0; i < 4; i++) {
      const sway = Math.sin(phase * 0.45 + i * 1.8);
      const startX = width * (0.08 + i * 0.27) + driftX;
      const endX = width * (0.82 - i * 0.19) + sway * width * 0.12;
      const gradient = ctx.createLinearGradient(startX, 0, endX, height);
      gradient.addColorStop(0, 'rgba(238, 133, 181, 0)');
      gradient.addColorStop(0.3, 'rgba(238, 133, 181, 0.5)');
      gradient.addColorStop(0.6, 'rgba(221, 151, 215, 0.35)');
      gradient.addColorStop(1, 'rgba(238, 133, 181, 0)');
      ctx.beginPath();
      ctx.moveTo(startX, -height * 0.2);
      ctx.bezierCurveTo(startX + sway * width * 0.25, height * 0.3,
        endX - sway * width * 0.2, height * 0.6, endX, height * 1.2);
      ctx.strokeStyle = gradient;
      ctx.lineWidth = Math.max(20, width * 0.035);
      ctx.shadowColor = '#ee85b5';
      ctx.shadowBlur = 28;
      ctx.stroke();
      ctx.lineWidth = 3;
      ctx.strokeStyle = 'rgba(255, 224, 238, 0.75)';
      ctx.stroke();
    }
    ctx.shadowBlur = 0;
  }

  function drawTrail(now) {
    if (!trailCtx) return;
    trailCtx.clearRect(0, 0, width, height);
    while (points.length && now - points[0].time > 420) points.shift();
    for (const point of points) {
      const life = 1 - (now - point.time) / 420;
      trailCtx.fillStyle = `rgba(198, 75, 128, ${life * 0.4})`;
      trailCtx.beginPath();
      trailCtx.arc(point.x, point.y, 2 * life, 0, Math.PI * 2);
      trailCtx.fill();
    }
  }

  function render(now) {
    frame = 0;
    if (document.hidden || reducedMotion.matches) return;
    // Cap at 30 fps and bound trail points for long reading sessions.
    if (now - lastFrame >= 32) {
      phase += Math.min((now - lastFrame) / 1000, 0.05);
      lastFrame = now;
      drawBeams();
      drawTrail(now);
      if (spotlight) {
        const rect = spotlight.getBoundingClientRect();
        spotlight.style.setProperty('--mx', (pointerX - rect.left) + 'px');
        spotlight.style.setProperty('--my', (pointerY - rect.top) + 'px');
      }
    }
    frame = requestAnimationFrame(render);
  }

  function syncAnimation() {
    if (frame) cancelAnimationFrame(frame);
    frame = 0;
    points.length = 0;
    if (trailCtx) trailCtx.clearRect(0, 0, width, height);
    if (!document.hidden && !reducedMotion.matches) {
      lastFrame = performance.now();
      frame = requestAnimationFrame(render);
    } else {
      ctx.clearRect(0, 0, width, height);
    }
  }

  document.addEventListener('pointermove', (event) => {
    if (!finePointer.matches || reducedMotion.matches || event.pointerType === 'touch') return;
    pointerX = event.clientX;
    pointerY = event.clientY;
    pointerActive = true;
    spotlight = event.target instanceof Element ? event.target.closest('.index-post') : null;
    points.push({ x: pointerX, y: pointerY, time: performance.now() });
    if (points.length > 48) points.shift();
  }, { passive: true });
  document.documentElement.addEventListener('pointerleave', () => {
    pointerActive = false;
    spotlight = null;
  });
  window.addEventListener('resize', resize, { passive: true });
  document.addEventListener('visibilitychange', syncAnimation);
  reducedMotion.addEventListener('change', syncAnimation);
  finePointer.addEventListener('change', syncAnimation);
  resize();
  syncAnimation();
})();
